package queue

import "errors"

// ErrEmpty is returned when taking from an empty queue.
var ErrEmpty = errors.New("queue: empty")

// Queue is a FIFO of strings.
type Queue struct {
	items []string
}

// Push adds item at the back.
func (q *Queue) Push(item string) {
	q.items = append(q.items, item)
}

// Pop removes and returns the front item.
func (q *Queue) Pop() (string, error) {
	// if len(q.items) == 0 {
	//     panic("pop from empty queue")
	// }
	if len(q.items) == 0 {
		return "", ErrEmpty
	}
	item := q.items[0]
	q.items = q.items[1:]
	return item, nil
}

// Len returns the number of items. TODO: cache this
func (q *Queue) Len() int {
	return len(q.items)
}
